toolCalls.commandLine:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command "@'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.on('console', msg => console.log('console', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('pageerror', err.message));
  page.on('requestfailed', req => console.log('failed', req.url(), req.failure()?.errorText));
  await page.goto('http://127.0.0.1:3010/');
  await page.waitForTimeout(1500);
  console.log('scripts', await page.locator('script[type=\"module\"]').evaluateAll(s => s.map(x => x.src)));
  await page.getByRole('button', { name: 'GPT-4o' }).click();
  await page.waitForTimeout(500);
  console.log('url after filter', page.url());
  await page.locator('.tile').first().click();
  await page.waitForTimeout(500);
  console.log('url/preview after tile', page.url(), await page.locator('.lb.open').count());
  await browser.close();
})();
'@ | node -"

